<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Media; use Illuminate\Http\Request;
class MediaController extends Controller {public function index(){return view('admin.media.index',['items'=>Media::latest()->paginate(30)]);}public function store(Request $r){$d=$r->validate(['file'=>'required|file|mimes:jpg,jpeg,png,webp,avif|max:5120','alt_text'=>'nullable|max:255']);$f=$r->file('file');$path=$f->store('media','public');Media::create(['uploaded_by'=>$r->user()->id,'disk'=>'public','path'=>$path,'original_name'=>$f->getClientOriginalName(),'mime_type'=>$f->getMimeType(),'size_bytes'=>$f->getSize(),'alt_text'=>$d['alt_text']??null]);return back()->with('success','Media uploaded.');}public function destroy(Media $media){\Storage::disk($media->disk)->delete($media->path);$media->delete();return back()->with('success','Media deleted.');}}
